document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("wishlist-grid"),n=document.getElementById("wishlist-empty");if(!e||typeof PRODUCTS=="undefined")return;function d(){const s=getWishlist(),i=PRODUCTS.filter(t=>s.includes(t.id));e.innerHTML=i.map(productCardHTML).join(""),e.hidden=!i.length,n&&(n.hidden=i.length>0),bindWishlistButtons(e),e.querySelectorAll(".pc-wishlist").forEach(t=>t.addEventListener("click",()=>setTimeout(d,0))),e.querySelectorAll(".reveal").forEach(t=>t.classList.add("visible","in","is-visible"))}d()});
